export const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]??paths.grid}"/></svg>`;
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const num=(v,d=0)=>v===null||v===undefined||!Number.isFinite(Number(v))?'—':Number(v).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
export const compact=v=>v===null||v===undefined?'—':Math.abs(v)>=1e6?(v/1e6).toFixed(2)+'M':Math.abs(v)>=1e3?(v/1e3).toFixed(1)+'k':num(v,1);
export const pct=(v,d=1)=>v===null||v===undefined?'—':num(v*100,d)+'%';
export const metricValue=(v,key='')=>typeof v==='string'?esc(v):v===null||v===undefined?'—':Math.abs(v)<.0001&&v!==0?Number(v).toExponential(2):/F1|precision|recall|AUC|MRR|Hits|r2|R2/i.test(key)?num(v,3):num(v,3);
export const chip=(s,t='')=>`<span class="chip ${t}">${esc(s)}</span>`;
export const btn=(label,action,{primary=false,ic=null,small=false,attrs=''}={})=>`<button class="btn ${primary?'primary':''} ${small?'small':''}" data-action="${action}" ${attrs}>${ic?icon(ic):''}${esc(label)}</button>`;
export const panel=(title,body,{ic=null,right='',note='',cls=''}={})=>`<section class="panel ${cls}"><div class="panel-head"><h2>${ic?icon(ic):''}${title}</h2>${right}</div>${body}${note?`<div class="panel-note">${icon('info')}${note}</div>`:''}</section>`;
export const metric=(label,value,sub='',color='')=>`<div class="metric"><label>${esc(label)}</label><strong class="${color}">${value}</strong>${sub?`<small>${esc(sub)}</small>`:''}</div>`;
export function splitBar(split={train:70,validation:15,test:15},unit='条'){const a=Number(split.train??0),b=Number(split.validation??0),c=Number(split.test??0),n=a+b+c||1;return`<div class="split-bar"><i style="width:${a/n*100}%"></i><i style="width:${b/n*100}%"></i><i style="width:${c/n*100}%"></i></div><div class="split-labels">${[['训练',a,'teal'],['验证',b,'blue'],['测试',c,'amber']].map(([name,v,cl])=>`<span><i class="legend-dot" style="background:var(--${cl})"></i>${name} <strong>${num(v)}</strong>${unit} · ${num(v/n*100,1)}%</span>`).join('')}</div>`;}
export function table(rows,columns,{limit=8,selectable=false}={}){if(!rows?.length)return'<div class="empty-inline">当前没有可显示的记录</div>';return`<div class="table-scroll"><table class="data-table"><thead><tr>${columns.map(c=>`<th>${esc(c.label??c.key)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,limit).map((r,i)=>`<tr ${selectable?`data-row="${i}"`:''}>${columns.map(c=>{const v=r[c.key];return`<td class="${c.text?'text':''}">${c.render?c.render(v,r,i):v===null||v===undefined||v===''?'<span class="missing">缺失</span>':typeof v==='number'?num(v,c.decimals??2):esc(String(v))}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`;}
export const notice=(text,amber=false)=>`<div class="notice ${amber?'amber':''}">${icon(amber?'warning':'info')}<div>${text}</div></div>`;
export const empty=text=>`<div class="empty">${icon('scan')}<h3>${esc(text)}</h3><p>选择数据并运行分析后查看结果与证据</p></div>`;
export function download(obj,name){const text=typeof obj==='string'?obj:JSON.stringify(obj,null,2),blob=new Blob([text],{type:name.endsWith('.csv')?'text/csv;charset=utf-8':'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
